create table if not exists public.articles(id uuid primary key default gen_random_uuid(),title text not null,slug text unique not null,excerpt text not null,body text not null,category text not null,image_url text,status text not null default 'draft' check(status in('draft','review','published','archived')),author_id uuid references auth.users(id) on delete set null,published_at timestamptz,created_at timestamptz not null default now());alter table public.articles enable row level security;create policy "Public reads published" on public.articles for select using(status='published');create policy "Editors read all" on public.articles for select to authenticated using(true);create policy "Editors insert own" on public.articles for insert to authenticated with check(auth.uid()=author_id);create policy "Editors update" on public.articles for update to authenticated using(true) with check(true);